import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import prettier from "prettier";
import ts from "typescript";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const runtimeWasmDir = path.resolve(__dirname, "../../runtime/src/wasm");
const dslRuntimeDir = path.resolve(__dirname, "../src/codegen/runtime");

function collectTsFiles(dir, baseDir = dir) {
  const results = [];
  if (!fs.existsSync(dir)) return results;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectTsFiles(fullPath, baseDir));
    } else if (entry.isFile() && entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts")) {
      results.push({
        fullPath,
        relPath: path.relative(baseDir, fullPath).replace(/\\/g, "/"),
        basename: entry.name,
      });
    }
  }
  return results;
}

const runtimeFiles = collectTsFiles(runtimeWasmDir);
const dslFiles = collectTsFiles(dslRuntimeDir).filter((file) => {
  // If a file is a local shim pointing to runtimeWasmDir (e.g. arena.ts), skip it
  return !runtimeFiles.some((rf) => rf.basename === file.basename && rf.relPath === file.relPath);
});

const allFiles = [...runtimeFiles, ...dslFiles];

let out = "/* eslint-disable */\n// AUTO-GENERATED BY scripts/bundle-templates.js\n// @ts-nocheck\n\n";
let dtsOut = "/* eslint-disable */\n// AUTO-GENERATED BY scripts/bundle-templates.js\n\n";

const templateEntries = [];
const rootShims = [];

for (const file of allFiles) {
  const content = fs.readFileSync(file.fullPath, "utf-8");
  let cleaned = content
    .replace("// @ts-nocheck\n", "")
    .replace(/\\/g, "\\\\")
    .replace(/\`/g, "\\`")
    .replace(/\$/g, "\\$");

  let varName;
  if (file.relPath === "dae/builder.ts") {
    varName = "daeBuilderCode";
  } else if (file.relPath === "dae/types.ts") {
    varName = "daeTypesCode";
  } else if (file.relPath === "dae/accessors.ts") {
    varName = "daeAccessorsCode";
  } else if (file.relPath === "analysis/coloring.ts") {
    varName = "analysisColoringCode";
  } else {
    varName = file.basename.replace(".ts", "Code").replace(/-([a-z])/g, function (g) {
      return g[1].toUpperCase();
    });
  }

  out += `export const ${varName} = \`${cleaned}\`;\n\n`;
  dtsOut += `export declare const ${varName}: string;\n`;

  // Also export camelCase alias if varName contains underscores
  if (varName.includes("_")) {
    const camelVarName = varName.replace(/_([a-z0-9])/g, function (_, char) {
      return char.toUpperCase();
    });
    if (camelVarName !== varName) {
      out += `export const ${camelVarName} = ${varName};\n\n`;
      dtsOut += `export declare const ${camelVarName}: string;\n`;
    }
  }

  // Do not include dynamically generated files (parser.ts, graph.ts) in runtimeTemplateFiles
  if (file.relPath !== "parser.ts" && file.relPath !== "graph.ts") {
    templateEntries.push({
      filename: file.relPath,
      varName,
    });
  }

  // Collect root shim for files located inside subdirectories
  if (file.relPath.includes("/")) {
    const subDir = path.dirname(file.relPath);
    if (subDir === "dae") {
      if (file.basename !== "types.ts" && file.basename !== "accessors.ts" && file.basename !== "builder.ts") {
        rootShims.push({
          filename: file.basename,
          content: `export * from "./${subDir}/${file.basename.replace(/\.ts$/, "")}";\n`,
        });
      }
    } else {
      rootShims.push({
        filename: file.basename,
        content: `export * from "./${subDir}/${file.basename.replace(/\.ts$/, "")}";\n`,
      });
      if (file.basename.includes("_")) {
        const hyphenatedName = file.basename.replace(/_/g, "-");
        rootShims.push({
          filename: hyphenatedName,
          content: `export * from "./${subDir}/${file.basename.replace(/\.ts$/, "")}";\n`,
        });
      }
    }
  }
}

// Add composite dae.ts shim
const daeShimContent = `export * from "./dae/types";\nexport * from "./dae/builder";\nexport * from "./dae/accessors";\n`;
rootShims.push({
  filename: "dae.ts",
  content: daeShimContent,
});

// Backward-compatible exports
out += `export const daeCode = \`${daeShimContent}\`;\n\n`;
dtsOut += `export declare const daeCode: string;\n`;

out += `export const builderCode = daeBuilderCode;\nexport const accessorsCode = daeAccessorsCode;\n\n`;
dtsOut += `export declare const builderCode: string;\nexport declare const accessorsCode: string;\n`;

let tsOut = out;
let jsOut = out;

// Export runtimeTemplateFiles manifest
tsOut += "export interface RuntimeTemplateFile {\n  filename: string;\n  content: string;\n}\n\n";
dtsOut += "export interface RuntimeTemplateFile {\n  filename: string;\n  content: string;\n}\n\n";

tsOut += "export const runtimeTemplateFiles: RuntimeTemplateFile[] = [\n";
jsOut += "export const runtimeTemplateFiles = [\n";
for (const entry of templateEntries) {
  const line = `  { filename: "${entry.filename}", content: ${entry.varName} },\n`;
  tsOut += line;
  jsOut += line;
}
tsOut += "];\n\n";
jsOut += "];\n\n";
dtsOut += "export declare const runtimeTemplateFiles: RuntimeTemplateFile[];\n";

tsOut += "export const rootShimFiles: RuntimeTemplateFile[] = [\n";
jsOut += "export const rootShimFiles = [\n";
for (const shim of rootShims) {
  const line = `  { filename: "${shim.filename}", content: ${JSON.stringify(shim.content)} },\n`;
  tsOut += line;
  jsOut += line;
}
tsOut += "];\n\n";
jsOut += "];\n\n";
dtsOut += "export declare const rootShimFiles: RuntimeTemplateFile[];\n";

// Also bundle the JS wrapper template, compiling it at build-time
const wrapperTemplatePath = path.resolve(__dirname, "../src/bindings/javascript/bindings.ts");
if (fs.existsSync(wrapperTemplatePath)) {
  const content = fs.readFileSync(wrapperTemplatePath, "utf-8");

  const options = {
    module: ts.ModuleKind.ESNext,
    target: ts.ScriptTarget.ES2022,
    declaration: true,
  };

  const createdFiles = {};
  const host = ts.createCompilerHost(options);
  const originalGetSourceFile = host.getSourceFile;
  host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
    if (fileName === "bindings.ts") {
      return ts.createSourceFile(fileName, content, languageVersion);
    }
    return originalGetSourceFile(fileName, languageVersion, onError, shouldCreateNewSourceFile);
  };
  host.writeFile = (fileName, contents) => {
    createdFiles[fileName] = contents;
  };

  const program = ts.createProgram(["bindings.ts"], options, host);
  program.emit();

  let jsCode = createdFiles["bindings.js"] || "";
  let dtsCode = createdFiles["bindings.d.ts"] || "";

  // Format compiled code with Prettier so downstream generated bindings.js/.d.ts match repo formatting
  try {
    jsCode = await prettier.format(jsCode, { parser: "babel" });
    dtsCode = await prettier.format(dtsCode, { parser: "typescript" });
  } catch (err) {
    console.warn("Prettier formatting warning in bundle-templates:", err);
  }

  const jsCleaned = jsCode.replace(/\\/g, "\\\\").replace(/\`/g, "\\`").replace(/\$/g, "\\$");
  const dtsCleaned = dtsCode.replace(/\\/g, "\\\\").replace(/\`/g, "\\`").replace(/\$/g, "\\$");

  tsOut += `export const bindingsTemplateJsCode = \`${jsCleaned}\`;\n\n`;
  tsOut += `export const bindingsTemplateDtsCode = \`${dtsCleaned}\`;\n\n`;
  jsOut += `export const bindingsTemplateJsCode = \`${jsCleaned}\`;\n\n`;
  jsOut += `export const bindingsTemplateDtsCode = \`${dtsCleaned}\`;\n\n`;
  dtsOut += `export declare const bindingsTemplateJsCode: string;\n`;
  dtsOut += `export declare const bindingsTemplateDtsCode: string;\n`;
}

for (const targetDir of [
  path.resolve(__dirname, "../build/src-gen"),
  path.resolve(__dirname, "../src/src-gen"),
  path.resolve(__dirname, "../dist/src-gen"),
]) {
  if (!fs.existsSync(targetDir)) {
    fs.mkdirSync(targetDir, { recursive: true });
  }
  fs.writeFileSync(path.resolve(targetDir, "runtime-templates.js"), jsOut, "utf-8");
  fs.writeFileSync(path.resolve(targetDir, "runtime-templates.ts"), tsOut, "utf-8");
  fs.writeFileSync(path.resolve(targetDir, "runtime-templates.d.ts"), dtsOut, "utf-8");
  console.log(`Bundled templates into ${targetDir}`);
}
